// ANCHOR: example
//! A gRPC client that uses gRPC-Web in the browser and HTTP/2 elsewhere.
//!
//! The message types and the client are written by hand to keep the example
//! self-contained; in a real project they are generated by `tonic-build` from
//! a `.proto` file.

use tonic::client::Grpc;
use tonic::codegen::http::uri::PathAndQuery;
use tonic_prost::ProstCodec;

#[derive(Clone, PartialEq, Eq, prost::Message)]
pub struct HelloRequest {
    #[prost(string, tag = "1")]
    pub name: String,
}

#[derive(Clone, PartialEq, Eq, prost::Message)]
pub struct HelloReply {
    #[prost(string, tag = "1")]
    pub message: String,
}

/// Browser: `tonic-web-wasm-client` speaks gRPC-Web over `fetch`.
#[cfg(target_arch = "wasm32")]
pub async fn say_hello(
    url: String,
    name: String,
) -> Result<String, tonic::Status> {
    let client = tonic_web_wasm_client::Client::new(url);
    call(Grpc::new(client), name).await
}

/// Native targets: a regular tonic `Channel`.
#[cfg(not(target_arch = "wasm32"))]
pub async fn say_hello(
    url: String,
    name: String,
) -> Result<String, tonic::Status> {
    let channel = tonic::transport::Endpoint::from_shared(url)
        .map_err(|e| tonic::Status::invalid_argument(e.to_string()))?
        .connect_lazy();
    call(Grpc::new(channel), name).await
}

/// The call itself is the same on both targets.
async fn call<T>(
    mut grpc: Grpc<T>,
    name: String,
) -> Result<String, tonic::Status>
where
    T: tonic::client::GrpcService<tonic::body::Body>,
    T::Error: Into<tonic::codegen::StdError>,
    T::ResponseBody:
        tonic::codegen::Body<Data = tonic::codegen::Bytes> + Send + 'static,
    <T::ResponseBody as tonic::codegen::Body>::Error:
        Into<tonic::codegen::StdError> + Send,
{
    grpc.ready()
        .await
        .map_err(|_| tonic::Status::unavailable("service not ready"))?;
    let path = PathAndQuery::from_static("/helloworld.Greeter/SayHello");
    let reply: tonic::Response<HelloReply> = grpc
        .unary(
            tonic::Request::new(HelloRequest { name }),
            path,
            ProstCodec::default(),
        )
        .await?;
    Ok(reply.into_inner().message)
}
// ANCHOR_END: example

#[cfg(test)]
mod tests {
    use prost::Message;

    use super::*;

    #[test]
    fn messages_round_trip() -> anyhow::Result<()> {
        let bytes = HelloRequest { name: "Ann".into() }.encode_to_vec();
        assert_eq!(HelloRequest::decode(bytes.as_slice())?.name, "Ann");
        Ok(())
    }

    #[tokio::test]
    async fn unreachable_server_is_an_error() {
        // Port 1 is not listening: the call fails with a `Status`, not a panic.
        let result = say_hello("http://127.0.0.1:1".into(), "Ann".into()).await;
        assert!(result.is_err());
    }
}
